package org.sleepwell.app;

import org.junit.Test;
import static org.junit.Assert.*;
import java.util.*;

public class PowerMenuGuardTest {
    private static final String MENU="com.android.systemui.globalactions.GlobalActionsDialogLite$ActionsDialog",SAMSUNG="com.samsung.android.globalactions.presentation.view.SamsungGlobalActionsDialogBase$ActionsDialog";
    static class Fixture {boolean allowed=true,backResult=true;int backs,returns;long now=1000;List<Runnable> pending=new ArrayList<>();PowerMenuGuard guard=new PowerMenuGuard((delay,callback)->{assertEquals(150,delay);pending.add(callback);},()->allowed,()->{backs++;return backResult;},()->returns++,()->now);void run(){List<Runnable> copy=new ArrayList<>(pending);pending.clear();copy.forEach(Runnable::run);}}
    @Test public void knownAospAndSamsungMenusAreRecognisedWithoutScreenContents(){assertTrue(PowerMenuGuard.powerWindow("com.android.systemui","com.android.systemui.globalactions.GlobalActionsDialogLite$ActionsDialog"));assertTrue(PowerMenuGuard.powerWindow("android","com.samsung.android.globalactions.presentation.view.SamsungGlobalActionsDialogBase$ActionsDialog"));assertTrue(PowerMenuGuard.powerWindow("android","com.android.internal.policy.impl.GlobalActions"));}
    @Test public void genericDialogsSettingsCallsAndSpoofedPackagesNeverMatch(){for(String[] window:new String[][]{{"com.android.systemui","android.app.Dialog"},{"com.android.settings",MENU},{"com.android.emergency",MENU},{"com.samsung.android.dialer",MENU},{"example.globalactions",MENU},{null,MENU},{"android",null},{"com.android.systemui","EmergencyActionDialog"}})assertFalse(Arrays.toString(window),PowerMenuGuard.powerWindow(window[0],window[1]));}
    @Test public void nestedEmergencyAndSosDialogsNeverMatch(){for(String name:new String[]{MENU+"$EmergencyActionDialog",SAMSUNG+"$SosDialog","com.android.systemui.globalactions.EmergencyGlobalActionsDialog","com.android.systemui.globalactions.GlobalActionsDialogLite$OtherDialog"})assertFalse(name,PowerMenuGuard.powerWindow("com.android.systemui",name));}
    @Test public void focusChangeOrUnknownWindowIdPreventsStaleBack(){Fixture f=new Fixture();f.guard.window("android",MENU,10);f.guard.focus(11);f.run();assertEquals(0,f.backs);f.guard.window("android",MENU,-1);f.run();assertEquals(0,f.backs);}
    @Test public void recognisedMenuUsesDelayedBackThenReturnsToChallenge(){Fixture f=new Fixture();f.guard.window("android",SAMSUNG,10);assertEquals(0,f.backs);f.run();assertEquals(1,f.backs);assertEquals(1,f.returns);}
    @Test public void bothGuardsRequireLiveServiceAndRealRingingOccurrence(){for(int id:new int[]{1,2,1999001,Integer.MAX_VALUE})assertTrue(PowerMenuGuard.activeAlarm(true,true,id));assertFalse(PowerMenuGuard.activeAlarm(false,true,1));assertFalse(PowerMenuGuard.activeAlarm(true,false,1));assertFalse(PowerMenuGuard.activeAlarm(true,true,0));assertFalse(PowerMenuGuard.activeAlarm(true,true,-1));assertTrue(PowerMenuGuard.systemPackage("android"));assertTrue(PowerMenuGuard.systemPackage("com.samsung.android.systemui"));assertFalse(PowerMenuGuard.systemPackage("example.systemui"));}
    @Test public void newWindowCancelsStaleBackIncludingEmergencyTransition(){Fixture f=new Fixture();f.guard.window("android",SAMSUNG,10);f.guard.window("com.samsung.android.dialer","EmergencyDialer",11);f.run();assertEquals(0,f.backs);}
    @Test public void dismissedAlarmOrDisabledToggleCancelsPendingAction(){Fixture f=new Fixture();f.guard.window("android",MENU,10);f.allowed=false;f.run();assertEquals(0,f.backs);f.guard.window("android",MENU,10);assertTrue(f.pending.isEmpty());}
    @Test public void serviceClosureAndInterruptionInvalidateCallbacks(){Fixture f=new Fixture();f.guard.window("android",MENU,10);f.guard.cancel();f.run();assertEquals(0,f.backs);f.guard.window("android",MENU,10);f.guard.close();f.run();assertEquals(0,f.backs);}
    @Test public void failedBackDoesNotRepeatedlyPullOtherWindowsForward(){Fixture f=new Fixture();f.backResult=false;f.guard.window("android",MENU,10);f.run();assertEquals(1,f.backs);assertEquals(0,f.returns);f.guard.window("android",MENU,10);f.run();assertEquals(1,f.backs);f.now+=501;f.guard.window("android",MENU,10);f.run();assertEquals(2,f.backs);}
}
